ound:#f8ece5}.patient-details{display:flex;flex-wrap:wrap;gap:8px;margin-top:13px;color:#758175;font-size:10px}.patient-details span{padding:6px 7px;background:#f7f8f4;border-radius:6px}.patient-details i{color:#759176}.patient-notes{margin:11px 0;color:#738073;font-size:10px;line-height:1.5}.patient-actions{display:flex;gap:5px;margin-top:13px}.patient-actions form{margin:0}.patient-actions button{min-height:29px;padding:0 8px;color:#5c6e5d;background:#f1f4ef;border:1px solid #e5eae2;border-radius:6px;cursor:pointer;font-size:9px;font-weight:700}.patient-actions .delete{color:#a14f43;background:#fbf0ed}.patient-dialog{width:min(calc(100% - 30px),580px);max-height:calc(100vh - 30px);padding:0;overflow:auto;border:1px solid #dce5d9;border-radius:13px}.patient-dialog::backdrop{background:rgba(38,56,47,.4)}.patient-dialog>div{display:flex;justify-content:space-between;padding:18px 20px;background:#f3f7f0}.patient-dialog>div button{border:0;background:transparent;cursor:pointer}.patient-dialog form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:20px}.patient-dialog footer{display:flex;justify-content:flex-end;gap:7px;grid-column:1/-1}.patient-dialog footer button{min-height:36px;padding:0 12px;border-radius:7px;border:1px solid #dfe5dc;background:#fff;cursor:pointer}.patient-dialog footer button[type=submit]{color:#fff;background:var(--green-dark);border-color:var(--green-dark)}@media(max-width:720px){.patient-form{grid-template-columns:repeat(2,minmax(0,1fr))}.patient-grid{grid-template-columns:1fr}}@media(max-width:520px){.patient-form,.patient-dialog form{grid-template-columns:1fr}.wide{grid-column:auto}.patient-form{padding-right:14px;padding-left:14px}}</style>
